package com.centralplay.app.ui;

import android.content.Context;import android.view.*;import android.view.animation.AnimationUtils;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.centralplay.app.R;import com.centralplay.app.data.*;import com.centralplay.app.model.*;import java.util.*;
public class ContentAdapter extends RecyclerView.Adapter<ContentAdapter.Holder>{public interface Listener{void onClick(Row row);void onLongClick(Row row);}public static class Row{public MediaEntry media;public SeriesEntry series;static Row media(MediaEntry m){Row r=new Row();r.media=m;return r;}static Row series(SeriesEntry s){Row r=new Row();r.series=s;return r;}String id(){return series!=null?series.id:media.id;}String title(){return series!=null?series.title:media.title;}String poster(){return series!=null?series.posterUrl:media.posterUrl;}boolean adult(){return series!=null?series.adult:media.adult;}String type(){return series!=null?"SERIE":("live".equals(media.type)?"EN VIVO":"PELÍCULA");}String subtitle(){if(series!=null)return(series.year==null?"":series.year)+(series.episodes==null?"":" · "+series.episodes.size()+" episodios");if("live".equals(media.type))return media.nowTitle==null||media.nowTitle.trim().isEmpty()?(media.group==null?"":media.group):"Ahora: "+media.nowTitle;String y=media.year==null?"":media.year;String rr=media.rating==null?"":media.rating;return y+(rr.trim().isEmpty()?"":" · ★ "+rr);}}private final Context context;private final Listener listener;private final List<Row> all=new ArrayList<>(),shown=new ArrayList<>();public ContentAdapter(Context c,Listener l){context=c;listener=l;setHasStableIds(true);}public void setRows(List<Row> rows,String query){all.clear();all.addAll(rows);shown.clear();String q=query==null?"":query.trim().toLowerCase(Locale.ROOT);for(Row r:all)if(q.isEmpty()||r.title().toLowerCase(Locale.ROOT).contains(q))shown.add(r);notifyDataSetChanged();}@Override public long getItemId(int p){return shown.get(p).id().hashCode();}@NonNull @Override public Holder onCreateViewHolder(@NonNull ViewGroup p,int v){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_content,p,false));}@Override public void onBindViewHolder(@NonNull Holder h,int p){Row r=shown.get(p);h.title.setText(r.title());h.subtitle.setText(r.subtitle());h.badge.setText(r.type());h.poster.setBackgroundResource(R.drawable.bg_poster_placeholder);ImageLoader.load(h.poster,r.poster());h.favorite.setAlpha(FavoritesStore.contains(context,r.id())?1f:.45f);h.favorite.setOnClickListener(v->{FavoritesStore.toggle(context,r.id());int pos=h.getBindingAdapterPosition();if(pos!=RecyclerView.NO_POSITION)notifyItemChanged(pos);});h.itemView.setOnFocusChangeListener((v,has)->{v.clearAnimation();v.startAnimation(AnimationUtils.loadAnimation(context,has?R.anim.scale_up:R.anim.scale_down));v.setElevation(has?14f:6f);});h.itemView.setOnClickListener(v->listener.onClick(r));h.itemView.setOnLongClickListener(v->{listener.onLongClick(r);return true;});}@Override public int getItemCount(){return shown.size();}static class Holder extends RecyclerView.ViewHolder{ImageView poster;TextView title,subtitle,badge;ImageButton favorite;Holder(View v){super(v);poster=v.findViewById(R.id.poster);title=v.findViewById(R.id.title);subtitle=v.findViewById(R.id.subtitle);badge=v.findViewById(R.id.type_badge);favorite=v.findViewById(R.id.favorite);}}}
